    def test_sign(
        self,
        name: str,
        seed: bytes,
        mu: bytes,
        sig_expected: bytes,
        valid: bool,
    ):
        _, sk = MlDsa44.key_gen(seed)

        if not valid:
            with self.assertRaises(ValueError):
                sk.sign_mu(mu, deterministic=True)
        else:
            sig = sk.sign_mu(mu, deterministic=True)
            self.assertEqual(sig, sig_expected)
